    "Reciprocity": {"Explanation": "The email offers something (over 2 million pre-ordered scripts) and asks for an action (buy now), which aligns with the principle of reciprocity."},
    "Scarcity": {"Explanation": "The email implies scarcity by mentioning 'Over 2 Million Pre-Ordered Scripts' and 'Lowest Price Guarantee', creating a sense of urgency to act quickly."},
    "Authority": {"Explanation": "Not present. There is no reference to a recognized institution, title, or role that would establish authority."},
    "Commitment/Consistency": {"Explanation": "Not present. There is no mention of prior behavior or choices to push further action."},
    "Liking": {"Explanation": "Not present. There is no use of familiarity, flattery, or personalization to build trust or rapport."},
    "Social proof": {"Explanation": "Not present. There is no reference to other people's participation or endorsement to influence the decision-making process."}
}

